          "sql": "SELECT 'abn' p, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95ms, round(avg(duration/1e6),1) avgms FROM abnormal_traces WHERE service_name='ts-admin-user-service' AND span_name='AdminUserController.getAllUsers' UNION ALL SELECT 'norm', count(*), round(approx_quantile(duration/1e6,0.95),1), round(avg(duration/1e6),1) FROM normal_traces WHERE service_name='ts-admin-user-service' AND span_name='AdminUserController.getAllUsers'",
          "claim": "getAllUsers internal span p95 rose from about 8 ms to about 1655 ms, across all 53 calls in the incident window."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.span_name, c.attr_span_kind, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) p95ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-admin-user-service' AND p.span_name='AdminUserController.getAllUsers' GROUP BY 1,2,3",
          "claim": "Its only child call (outgoing GET) takes about 11 ms, so the extra ~1640 ms is inside the method itself."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),2) avgv, round(max(value),2) maxv FROM abnormal_metrics WHERE service_name='ts-admin-user-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.pod.cpu_limit_utilization','k8s.pod.memory_limit_utilization') GROUP BY 1",
          "claim": "Pod CPU and memory stay low and flat during the slowdown, so container saturation is not the cause."
        },
        {
          "kind": "log",
          "sql": "SELECT level, left(message,120) m, count(*) n FROM abnormal_logs WHERE service_name='ts-admin-user-service' AND message LIKE '%getAllUsers%' GROUP BY 1,2",
          "claim": "getAllUsers logs only INFO success messages, with no errors, consistent with slow self-time rather than failure."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-admin-user-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name='GET /api/v1/adminuserservice/users' GROUP BY 1,2 UNION ALL SELECT service_name, span_name, count(*), round(approx_quantile(duration/1e6,0.95),1) FROM normal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name='GET /api/v1/adminuserservice/users' GROUP BY 1,2",
          "claim": "The user-facing dashboard request GET /adminuserservice/users went from about 13 ms p95 to about 1662 ms p95."
        }
      ]
    }
  ]
}
